insert into public.rate_schedules (id, union_id, title, production_type, effective_from, effective_to, columns, hourly_column, daily_column, rate_unit, source_url, notes) values
  ('iatse-212-high-budget-2026', 'u-212', 'IATSE 212 Motion Picture 2026, High Budget', 'High Budget', '2026-04-01', '2027-03-31', array['Hourly','Weekly'], 'Hourly', null, 'hourly', 'https://www.iatse212.com/downloads/agreements/2026RatesandFringesFinal.pdf', 'Budget tiers (Schedule A1): features over $19M, 1-hour episodes over $10M, half-hours over $5M per episode, and all unit shoots. Fringes on top: vacation pay 4% and holiday pay 3%, plus administration, pension and health set by tier.'),
  ('iatse-212-tier-a-2026', 'u-212', 'IATSE 212 Motion Picture 2026, Tier A', 'Tier A', '2026-04-01', '2027-03-31', array['Hourly','Weekly'], 'Hourly', null, 'hourly', 'https://www.iatse212.com/downloads/agreements/2026RatesandFringesFinal.pdf', 'Budget tiers (Schedule A1): features $10M to $19M, 1-hour episodes $1.75M to $10M, half-hours $950K to $5M per episode. Fringes on top: vacation pay 4% and holiday pay 3%, plus administration, pension and health set by tier.'),
  ('iatse-212-tier-b-2026', 'u-212', 'IATSE 212 Motion Picture 2026, Tier B', 'Tier B', '2026-04-01', '2027-03-31', array['Hourly','Weekly'], 'Hourly', null, 'hourly', 'https://www.iatse212.com/downloads/agreements/2026RatesandFringesFinal.pdf', 'Budget tiers (Schedule A1): features $5M to $10M, 1-hour episodes $750K to $1.75M, half-hours $500K to $950K per episode. Fringes on top: vacation pay 4% and holiday pay 3%, plus administration, pension and health set by tier.'),
  ('iatse-212-tier-c-2026', 'u-212', 'IATSE 212 Motion Picture 2026, Tier C', 'Tier C', '2026-04-01', '2027-03-31', array['Hourly','Weekly'], 'Hourly', null, 'hourly', 'https://www.iatse212.com/downloads/agreements/2026RatesandFringesFinal.pdf', 'Budget tiers (Schedule A1): features $3M to $5M, 1-hour episodes under $750K, half-hours under $500K per episode. Fringes on top: vacation pay 4% and holiday pay 3%, plus administration, pension and health set by tier.');
